import{_ as t}from"./chunks/image-002.Dp2-bnLm.js";import{_ as a,o as _,c as e,a3 as o}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/66-论邹第五十三.md","filePath":"books/yan-tie-lun/66-论邹第五十三.md","lastUpdated":1794316978000}'),n={name:"books/yan-tie-lun/66-论邹第五十三.md"};function s(r,p,i,l,c,d){return _(),e("div",null,[...p[0]||(p[0]=[o('<p>论邹第五十三 【题解】</p><p>本篇记载大夫与文学围绕如何评价战国阴阳家邹衍“大九州说”而展开的论辩。大夫盛赞邹衍学说境界弘阔，借此批评儒生目光狭隘，拘执一端，不知天下之义。文学贤良则认为邹衍学说实属“匹夫荧惑诸侯”，导致诸侯亡国破家的恶果。文学进一步指出，衡量思想学说的标准，不在于它所说的远近大小，而是要看它是否有利于治理国家。此前汉武帝曾经罢黜百家独尊儒术，身为御史大夫的桑弘羊却在官方场合公开褒扬邹衍贬斥儒学，由此透露出一个信息：即使在经学昌明时代，诸子百家之学也并未完全绝迹。</p><p>大夫曰：“邹子疾晚世之儒墨[(1)]，不知天地之弘[(2)]，昭旷之道[(3)]，将一曲而欲道九折[(4)]，守一隅而欲知万方[(5)]，犹无准平而欲知高下[(6)]，无规矩而欲知方圆也[(7)]。于是推大圣终始之运[(8)]，以喻王公[(9)]，先列中国名山通谷[(10)]，以至海外。所谓中国者，天下八十一分之一[(11)]，名曰赤县神州[(12)]，而分为九州[(13)]。绝陵陆不通[(14)]，乃为一州，有大瀛海圜其外[(15)]。此所谓八极[(16)]，而天地际焉[(17)]。《禹贡》亦著山川高下原隰[(18)]，而不知大道之径[(19)]。故秦欲达九州而方瀛海[(20)]，牧胡而朝万国[(21)]。诸生守畦亩之虑[(22)]，闾巷之固[(23)]，未知天下之义也。”</p><p>【注释】</p><p>[(1)]邹子：邹衍（约前305年—前240），战国阴阳家，提出“大九洲”地理学说和“五德终始”的历史哲学。邹，一作“驺”。疾：痛恨。</p><p>[(2)]弘：广阔，恢宏。</p><p>[(3)]昭旷：昭明辽阔。</p><p>[(4)]曲：隈曲，河湾。道：通。九折：多个曲折河湾。</p><p>[(5)]隅：墙角。万方：所有方向。</p><p>[(6)]准平：古代测平的仪器。</p><p>[(7)]规：校正圆形的工具。矩：校正方形的工具。</p><p>[(8)]推大圣终始之运：指邹衍五德终始的历史哲学。邹衍认为历代王朝的嬗变按照五行相胜（金胜木，木胜土，土胜水，水胜火，火胜金）的模式循环运行。受命帝王得五德中当运的一德，便有资格统治一个朝代。大圣终始，邹衍著作篇名，《史记·孟子荀卿列传》作“终始大圣之篇”。</p><p>[(9)]喻：告知，知晓。</p><p>[(10)]先列：原作“列土”，据张敦仁说校改。通谷：大峡谷，《史记·孟子荀卿列传》作“大川”。</p><p>[(11)]八十一分之一：原作“八十分之一”，据张敦仁说补“一”。</p><p>[(12)]赤县神州：这是邹衍给中国取的名称。</p><p>[(13)]分为九州：《史记·孟子荀卿列传》载：“以为儒者所谓中国者，于天下乃八十一分居其一分耳。中国名曰赤县神州。赤县神州内自有九州，禹之序九州是也，不得为州数。中国外与赤县神州者九，乃所谓九州也。”据此，邹衍“九州”相当于全世界。《尚书·禹贡》称大禹治水，曾将中国划分为九州：冀州、兖州、青州、徐州、扬州、荆州、豫州、梁州、雍州。禹所划分的九州——赤县神州——只占全世界的八十一分之一，与邹衍“九州”内涵不同。</p><p>[(14)]绝：隔绝。陵：丘陵。陆：陆地。</p><p>[(15)]瀛（yínɡ）海：大海。圜（huán）：环绕。</p><p>[(16)]八极：八方之极。</p><p>[(17)]天地：原作“天下”，据张敦仁说校改。际：交界。</p><p>[(18)]《禹贡》：《尚书》篇名，记载禹划分九州、山川方位走向以及物产贡赋交通情形。著：著录，记载。原隰（xí）：高平曰原，下湿曰隰。</p><p>[(19)]大道：指邹衍九州说。径：道路，路径。</p><p>[(20)]方：航渡。</p><p>[(21)]牧：统治。胡：指匈奴。朝：朝贡。此处用做使动词，使之朝贡。</p><p>[(22)]畦（qí）亩之虑：指境界狭小、不知变通的思维方式。畦亩，有土埂围着的排列整齐的田亩。</p><p>[(23)]闾（lǘ）巷：里弄。固：鄙陋。</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“邹衍痛恨后来的儒、墨之徒，他们不知天地的弘阔，不懂得宇宙广阔的道理，看到一个河湾就想通达所有河湾，守着一个墙角就想知道所有方向，这就如同没有测平仪器却想区分高下，没有圆规方矩却想知道方圆。邹衍于是推论《大圣终始》的气运，以此来晓喻王公大人，他先列举中国名山峡谷，以此推论到海外情形。邹衍认为儒、墨之徒所说的中国，在地理上只占天下八十一分之一，邹衍把中国取名叫赤县神州，中国之内被大禹分为小九州。其实，丘陵陆地隔绝不通，才可称为一州，一州之外有大海环绕着。这就是人们所说的八方之极，九州的边际就与天地接壤了。《尚书·禹贡》虽然也记载了中国山川高低和平原湿地，但《禹贡》却不能像邹衍那样明白天下大道理。因此秦王朝根据邹衍之说，试图通达天下九州，渡过大海，统治殊方异族，而使万国来朝。儒墨之徒只知道拘执于一田一亩的狭小思维方式，困守着一闾一巷的陋见，不知道天下大义。”</p><p>文学曰：“尧使禹为司空[(1)]，平水土，随山刊木[(2)]，定高下而序九州[(3)]。邹衍非圣人，作怪误[(4)]，荧惑六国之君[(5)]，以纳其说。此《春秋》所谓‘匹夫荧惑诸侯’者也[(6)]。孔子曰：‘未能事人，焉能事鬼神？’[(7)]近者不达[(8)]，焉能知瀛海？故无补于用者，君子不为；无益于治者，君子不由[(9)]。三王信经道[(10)]，而德光于四海[(11)]；战国信嘉言[(12)]，而破亡如丘山[(13)]。昔秦始皇已吞天下，欲并万国，亡其三十六郡[(14)]；欲达瀛海，而失其州县。知大义如斯[(15)]，不如守小计也[(16)]。”</p><p>【注释】</p><p>[(1)]司空：平治水土之官。尧任命禹为司空之事，见于《尚书·尧典》。</p><p>[(2)]刊：砍削。</p><p>[(3)]高下：指高山大川。序：次序，此处指划定、安排。</p><p>[(4)]怪误：奇怪欺骗之说。</p><p>[(5)]荧惑：迷惑，蛊惑。按，“荧”字原无，据王利器说校补。</p><p>[(6)]此《春秋》所谓“匹夫荧惑诸侯”者也：《史记·孔子世家》载：“孔子趋而进，历阶而登，不尽一等，曰：‘匹夫而荧惑诸侯者，罪当诛！’”事在鲁定公十年。《春秋》及三传均不载孔子此语。</p><p>[(7)]未能事人，焉能事鬼神：孔子此语见于《论语·先进》。今本《论语》无“神”字。</p><p>[(8)]达：通晓。</p><p>[(9)]由：实行。</p><p>[(10)]三王：夏、商、周三代之王。此外还有其他说法。经道：常道。</p><p>[(11)]光：读为“广”，广被。</p><p>[(12)]嘉言：好话，指蛊惑人心的言论。郭沫若说，“嘉”读为“讹”。</p><p>[(13)]破亡如丘山：原作“破亡而泥山”，据王利器说校改。</p><p>[(14)]三十六郡：秦始皇统一中国之后，将天下划分为三十六郡。</p><p>[(15)]大义：指蛊惑人心的言论，此处为反语。如斯：如此。</p><p>[(16)]小计：指“经道”。</p><p><img src="'+t+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“尧任命禹为司空，让他平治水土，随着山林形状，砍削树木作为路标，根据高山大河确定九州分界。邹衍不是圣人，他发表怪诞欺人的奇谈，蛊惑六国君主，以求诸侯采纳他的邪说。这就是《春秋》所说的‘匹夫蛊惑诸侯’的情形。孔子说：‘活人尚且不能服事，怎么能服事鬼神？’附近的事尚且不明白，怎么能知道远方的大海情形？因此对实用无补的事，君子不做；对于治国无益的事，君子不为。夏、商、周三王遵信常道，他们的德惠扩展到四海；战国诸侯听信蛊惑人心的动听言论，而破军亡国如同丘山崩溃。从前秦始皇吞并天下之后，想吞并天下万国，结果丢掉了秦朝的三十六郡；他想到达周边大海，结果失掉了秦朝的州县。像秦始皇这样知道邹衍的‘大义’，还不如恪守儒家的‘小计’。”</p>',51)])])}const y=a(n,[["render",s]]);export{u as __pageData,y as default};
